 function openTripAction(id:string,action:TripAction){tripReturn.current=[route==='chats'?'chats':'trips'];setCommerce(s=>({...s,selectedBooking:id}));if(action==='early'||action==='late'){setTimeServiceKind(action==='early'?'arrival':'departure');setEarlyOpen(true);}else if(action==='share')setShareOpen(true);else if(action==='key'){if(door.open(id,failKey?'failure':'success'))setFailKey(false);}else if(action==='wifi')setWifiOpen(true);else if(action==='documents'){recordReturn.current='trips';setRecordDocuments(true);setEditBooking(false);go('booking-record');}else if(action==='rewards')go('rewards');else if(action==='repeat'){const b=commerce.bookings.find(b=>b.id===id);if(b){const h=catalog.hotels.find(h=>h.id===b.draft.hotelId)!;const next={...commerce,search:{...commerce.search,city:h.city}};try{setCommerce(startDraft(next,h.id,crypto.randomUUID()));hotelReturn.current='trips';go('booking-flow');}catch{setCommerce(next);go('find');setToast('Выберите новые даты поездки');}}}else go('trip-'+action);}
 function openNotification(id:string,preview?:NoticeItem){
  if(!user)return;setPushPreview(null);
  const context=preview&&preview.kind!=='price'&&!appNotices(commerce,user.phone).some(n=>n.id===id)?{...commerce,appNotices:[...(commerce.appNotices||[]),{...preview,kind:preview.kind,owner:user.phone,demo:true as const}]}:commerce;
  try{const target=notificationDestination(context,user.phone,id);let next=readAppNotices(commerce,user.phone,id);
   if(target.priceId){next=openPriceNotice(next,user.phone,target.priceId,crypto.randomUUID());}
   if(target.bookingId)next={...next,selectedBooking:target.bookingId};
   setCommerce(next);tripReturn.current=['notifications'];reviewReturn.current='notifications';setReviewRating(undefined);
   setNoticeLanding(['trips','rewards'].includes(target.route)?target.route:'');go(target.route);
  }catch(e){setCommerce(s=>readAppNotices(s,user.phone,id));setToast((e as Error).message);}
 }
