 function openSheet(value:string){keyboard.hide();searchSequence.current=value==='city'&&route==='find';searchSequenceHotel.current=undefined;if(value==='city'||value==='dates')searchReturn.current=['results','results-map'].includes(route)?route:'find';focusBeforeSheet.current=document.activeElement instanceof HTMLElement?document.activeElement:null;setSheet(value);}
